'use strict';

// MODULES //

var resolve = require( 'path' ).resolve;
var tape = require( 'tape' );
var tryRequire = require( '@stdlib/utils/try-require' );
var isnanf = require( '@stdlib/math/base/assert/is-nanf' );
var isPositiveZerof = require( '@stdlib/math/base/assert/is-positive-zerof' );
var isNegativeZerof = require( '@stdlib/math/base/assert/is-negative-zerof' );
var isAlmostSameValuef = require( '@stdlib/number/float32/base/assert/is-almost-same-value' );
var f32 = require( '@stdlib/number/float64/base/to-float32' );
var PINF = require( '@stdlib/constants/float32/pinf' );
var NINF = require( '@stdlib/constants/float32/ninf' );


// FIXTURES //

var data = require( './fixtures/julia/data.json' );
var largeNegative = require( './fixtures/julia/large_negative.json' );
var largePositive = require( './fixtures/julia/large_positive.json' );
var tinyNegative = require( './fixtures/julia/tiny_negative.json' );
var tinyPositive = require( './fixtures/julia/tiny_positive.json' );


// VARIABLES //

var cschf = tryRequire( resolve( __dirname, './../lib/native.js' ) );
var opts = {
	'skip': ( cschf instanceof Error )
};


// TESTS //

tape( 'main export is a function', opts, function test( t ) {
	t.ok( true, __filename );
	t.strictEqual( typeof cschf, 'function', 'main export is a function' );
	t.end();
});

tape( 'the function computes the hyperbolic cosecant', opts, function test( t ) {
	var expected;
	var x;
	var y;
	var e;
	var i;

	x = data.x;
	expected = data.expected;

	for ( i = 0; i < x.length; i++ ) {
		y = cschf( x[ i ] );
		e = f32( expected[ i ] );
		t.strictEqual( isAlmostSameValuef( y, e, 2 ), true, 'returns expected value' );
	}
	t.end();
});

tape( 'the function computes the hyperbolic cosecant (large negative values)', opts, function test( t ) {
	var expected;
	var x;
	var y;
	var e;
	var i;

	x = largeNegative.x;
	expected = largeNegative.expected;

	for ( i = 0; i < x.length; i++ ) {
		y = cschf( x[ i ] );
		e = f32( expected[ i ] );
		t.strictEqual( isAlmostSameValuef( y, e, 2 ), true, 'returns expected value' );
	}
	t.end();
});

tape( 'the function computes the hyperbolic cosecant (large positive values)', opts, function test( t ) {
	var expected;
	var x;
	var y;
	var e;
	var i;

	x = largePositive.x;
	expected = largePositive.expected;

	for ( i = 0; i < x.length; i++ ) {
		y = cschf( x[ i ] );
		e = f32( expected[ i ] );
		t.strictEqual( isAlmostSameValuef( y, e, 2 ), true, 'returns expected value' );
	}
	t.end();
});

tape( 'the function computes the hyperbolic cosecant (tiny negative values)', opts, function test( t ) {
	var expected;
	var x;
	var y;
	var e;
	var i;

	x = tinyNegative.x;
	expected = tinyNegative.expected;

	for ( i = 0; i < x.length; i++ ) {
		y = cschf( x[ i ] );
		e = f32( expected[ i ] );
		t.strictEqual( y, e, 'returns expected value' );
	}
	t.end();
});

tape( 'the function computes the hyperbolic cosecant (tiny positive values)', opts, function test( t ) {
	var expected;
	var x;
	var y;
	var e;
	var i;

	x = tinyPositive.x;
	expected = tinyPositive.expected;

	for ( i = 0; i < x.length; i++ ) {
		y = cschf( x[ i ] );
		e = f32( expected[ i ] );
		t.strictEqual( y, e, 'returns expected value' );
	}
	t.end();
});

tape( 'the function returns `NaN` if provided `NaN`', opts, function test( t ) {
	var v = cschf( NaN );
	t.strictEqual( isnanf( v ), true, 'returns expected value' );
	t.end();
});

tape( 'the function returns `+Infinity` if provided `+0`', opts, function test( t ) {
	var v = cschf( +0.0 );
	t.strictEqual( v, PINF, 'returns expected value' );
	t.end();
});

tape( 'the function returns `-Infinity` if provided `-0`', opts, function test( t ) {
	var v = cschf( -0.0 );
	t.strictEqual( v, NINF, 'returns expected value' );
	t.end();
});

tape( 'the function returns `+0` if provided `+Infinity`', opts, function test( t ) {
	var v = cschf( PINF );
	t.strictEqual( isPositiveZerof( v ), true, 'returns expected value' );
	t.end();
});

tape( 'the function returns `-0` if provided `-Infinity`', opts, function test( t ) {
	var v = cschf( NINF );
	t.strictEqual( isNegativeZerof( v ), true, 'returns expected value' );
	t.end();
});

tape( 'the function returns `+0` if provided a value greater than `~89.416`', opts, function test( t ) {
	var v;

	v = cschf( f32( 89.5 ) );
	t.strictEqual( isPositiveZerof( v ), true, 'returns expected value' );

	v = cschf( f32( 100.0 ) );
	t.strictEqual( isPositiveZerof( v ), true, 'returns expected value' );

	t.end();
});

tape( 'the function returns `-0` if provided a value less than `~-89.416`', opts, function test( t ) {
	var v;

	v = cschf( f32( -89.5 ) );
	t.strictEqual( isNegativeZerof( v ), true, 'returns expected value' );

	v = cschf( f32( -100.0 ) );
	t.strictEqual( isNegativeZerof( v ), true, 'returns expected value' );

	t.end();
});

tape( 'the function returns `+-Infinity` if provided a subnormal value whose reciprocal overflows', opts, function test( t ) {
	var v;

	v = cschf( f32( 1.0e-40 ) );
	t.strictEqual( v, PINF, 'returns expected value' );

	v = cschf( f32( -1.0e-40 ) );
	t.strictEqual( v, NINF, 'returns expected value' );

	t.end();
});

tape( 'the function is an odd function (cschf(-x) === -cschf(x))', opts, function test( t ) {
	var values;
	var v;
	var i;

	values = [ 0.1, 0.5, 0.625, 1.0, 2.0, 5.0, 10.0, 50.0, 80.0 ];
	for ( i = 0; i < values.length; i++ ) {
		v = f32( values[ i ] );
		t.strictEqual( cschf( -v ), -cschf( v ), 'returns expected value' );
	}
	t.end();
});
